from pathlib import Path
import json,re,datetime,yaml
root=Path(__file__).resolve().parents[2];slug='mumble-phone-walkie-talkie-guide'
s=(root/'src/content/blog'/f'{slug}.md').read_text();front=yaml.safe_load(s.split('---')[1]);cn,en=s.split('<!--EN-->')
checks={'titleLimits':all(len(front[k])<=60 for k in ['title','titleEn']),'descriptions':all(150<=len(front[k])<=160 for k in ['description','descriptionEn']),'wechat':len(front['wechatTitle'])<=30 and len(front['wechatDigest'])<=54,'dates':all(re.fullmatch(r'\d{4}-\d{2}-\d{2}',front[k]) for k in ['pubDate','updatedDate']),'category':front['category']=='Tech-News','tags':len(front['tags'])>=3,'bilingual':len(cn)>3000 and len(en)>3000,'copyright':s.count('© 2026 Author: Mycelium Protocol.')==2,'FAQ':'## 常见问题'in cn and '## FAQ'in en,'questionHeadings':len(re.findall(r'^##.*？',cn,re.M))>=2 and len(re.findall(r'^##.*\?',en,re.M))>=2,'primarySources':all(x in s for x in ['https://github.com/mumble-voip/mumble','https://gitlab.com/quite/mumla','https://github.com/zavitax/mumbleway']),'runtimeLimits':'未执行容器启动'in cn and 'did not start a server'in en,'sourceGap':'未核实对应公开源码'in cn and 'matching public source'in en,'privacyBoundary':'不等于服务器无法解密'in cn and 'different from end-to-end encryption'in en,'internalLink':'https://blog.mushroom.cv/blog/corespeed-tie-mac-studio-guide/'in s}
figs=list(root.glob('src/assets/images/'+slug+'-fig-*.png'));checks['figures']=len(figs)==3 and all(x.stat().st_size<90000 and s.count(x.name)==2 for x in figs);checks['hero']=(root/'src/assets/images'/f'{slug}-banner.jpg').stat().st_size<99000
x={'checkedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'passed':all(checks.values()),'checks':checks,'lengths':{k:len(front[k]) for k in ['title','titleEn','description','descriptionEn','wechatTitle','wechatDigest']},'manualReview':['BilingualBLUF/FAQ,plainexternalURLs,alttexts','Mumblers sourceunverified distinctfromMumbleWay andlegacyiOS','Officialregistrytag+platform verified;no runningserver/phonebenchmark','Two requiredcredentialsandpersistence;no exposedICEadmin','ExistingAstrometadata/headinganchors used;no schemachanges']}
Path(__file__).with_name('seo-geo-report.json').write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n');print(json.dumps(x,ensure_ascii=False));assert x['passed']
